761:     /// `source` supplies values for layouts that have no cheaper synthetic blank.
762:     /// `plans` must have been produced by [`blank_plans`] for `source`.
763:     fn take_pending_blanks_with_plans(
764:         &mut self,
765:         source: &RecordBatch,
766:         plans: &[BlankPlan],
767:     ) -> Result<Option<RecordBatch>> {
768:         if self.pending_blank_rows == 0 {
769:             return Ok(None);
770:         }
771:         debug_assert_eq!(source.num_rows(), 1);
772: 
773:         let chunk_size = self.pending_blank_rows.min(self.max_output_rows.get());
774:         let batch_offsets = (0..chunk_size).collect::<Vec<_>>();
775:         let with_source = add_blanks_with_plans(source.clone(), &batch_offsets, plans)?;
776:         // Offsets `0..n` put the blanks first and append the whole source, so exactly
777:         // one row -- the source itself -- has to come back off the end. Check the
778:         // coupling rather than only documenting it in `add_blanks`.
779:         debug_assert_eq!(with_source.num_rows(), chunk_size as usize + 1);
780:         self.pending_blank_rows -= chunk_size;
781:         Ok(Some(with_source.slice(0, chunk_size as usize)))
